WITH metrics AS (SELECT id, method, amount, paid_at, AVG(amount) OVER (PARTITION BY status ORDER BY amount, id ROWS BETWEEN 3 PRECEDING AND 1 PRECEDING) AS amount_avg_3_prior, SUM(amount) OVER (PARTITION BY method ORDER BY amount, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_amount, COUNT(amount) OVER (PARTITION BY order_id) AS order_id_count_amount FROM payments) SELECT CASE WHEN cumulative_amount >= 8728 THEN 'PREMIUM' ELSE 'STANDARD' END AS cumulative_amount_tier, DATE_TRUNC('WEEK', paid_at) AS week_start, method, (UNIX_TIMESTAMP(MAX(paid_at)) - UNIX_TIMESTAMP(MIN(paid_at))) / 60 AS span_minutes, MIN(paid_at) AS started_at, SORT_ARRAY(COLLECT_SET(method)) AS method_list, COUNT(DISTINCT method) AS distinct_methods, SIZE(COLLECT_SET(method)) AS num_methods, COUNT(CASE WHEN method = 'cash' THEN 1 END) AS cash_count, GROUPING_ID() AS gid FROM metrics GROUP BY GROUPING SETS ((CASE WHEN cumulative_amount >= 8728 THEN 'PREMIUM' ELSE 'STANDARD' END, DATE_TRUNC('WEEK', paid_at), method), (CASE WHEN cumulative_amount >= 8728 THEN 'PREMIUM' ELSE 'STANDARD' END, DATE_TRUNC('WEEK', paid_at)), ()) ORDER BY distinct_methods DESC;
